import java.util.*;

public class Main {
    static final int MOD = 1000000007;

    static long modpow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static class DisjointSet {
        int[] parent;
        int[] rank;
        int comps;

        public DisjointSet(int n) {
            parent = new int[n];
            rank = new int[n];
            comps = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int u) {
            if (parent[u] != u) {
                parent[u] = find(parent[u]);
            }
            return parent[u];
        }

        public void merge(int u, int v) {
            u = find(u);
            v = find(v);
            if (u == v) return;
            if (rank[u] > rank[v]) {
                int temp = u;
                u = v;
                v = temp;
            }
            parent[u] = v;
            if (rank[u] == rank[v]) {
                rank[v]++;
            }
            comps--;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        boolean[] seen = new boolean[(int)p];
        DisjointSet dsu = new DisjointSet((int)p);

        for (long i = 0; i < p; i++) {
            for (long j = i; !seen[(int)j]; j = (j * k) % p) {
                seen[(int)j] = true;
                dsu.merge((int)i, (int)j);
            }
        }

        int c = dsu.comps;
        if (k != 1) c--;

        System.out.println(modpow(p, c));
        sc.close();
    }
}
